"""Tool for batch processing multiple video storage URLs from VST."""

import json
import logging

from nat.builder.builder import Builder
from nat.builder.framework_enum import LLMFrameworkEnum
from nat.builder.function_info import FunctionInfo
from nat.cli.register_workflow import register_function
from nat.data_models.component_ref import FunctionRef
from nat.data_models.function import FunctionBaseConfig
from pydantic import BaseModel
from pydantic import Field

logger = logging.getLogger(__name__)


class StreamTimeRange(BaseModel):
    """Represents a stream_id with start and end time range."""

    stream_id: str = Field(..., description="UUID of the camera stream")
    start_time: str = Field(..., description="Start time in ISO 8601 UTC format (e.g., '2025-08-25T03:05:55.752Z')")
    end_time: str = Field(..., description="End time in ISO 8601 UTC format (e.g., '2025-08-25T03:06:15.752Z')")


class VSTBatchVideoStorageConfig(FunctionBaseConfig, name="vst_batch_video_storage"):
    """Configuration for the VST Batch Video Storage tool."""

    get_video_storage_url_tool: FunctionRef = Field(..., description="Reference to the vst_get_video_storage_url tool")
    default_expiry_minutes: str = Field(
        default="10080",  # 7 days
        description="Default expiration time in minutes for URLs",
    )
    default_container: str = Field(
        default="mp4",
        description="Default video container format",
    )


class VSTBatchVideoStorageInput(BaseModel):
    """Input for batch processing video storage URLs."""

    stream_time_ranges: list[StreamTimeRange] = Field(
        ..., description="List of stream_id with time ranges to process", min_length=1
    )
    expiry_minutes: str | None = Field(
        default=None, description="Optional expiration time in minutes for all URLs (overrides default)"
    )
    container: str | None = Field(
        default=None, description="Optional video container format (e.g., 'mp4', 'avi') for all videos"
    )
    configuration: str | None = Field(
        default=None,
        description="Optional JSON string for advanced video and overlay configuration to apply to all videos",
    )

    model_config = {"extra": "forbid"}


class VSTBatchVideoStorageOutput(BaseModel):
    """Output containing list of video URLs."""

    video_urls: list[str] = Field(..., description="List of temporary URLs for accessing the video files")
    processed_count: int = Field(..., description="Number of stream/time ranges successfully processed")
    errors: list[dict[str, str]] = Field(
        default_factory=list, description="List of any errors encountered during processing"
    )


@register_function(config_type=VSTBatchVideoStorageConfig, framework_wrappers=[LLMFrameworkEnum.LANGCHAIN])
async def vst_batch_video_storage(config: VSTBatchVideoStorageConfig, builder: Builder):
    """
    Batch process multiple video storage URL requests from VST.

    This tool takes a list of stream_id/time range tuples and calls the
    vst_get_video_storage_url tool for each tuple, collecting all the
    resulting video URLs into a single list.

    Example input:
    ```json
    {
        "stream_time_ranges": [
            {
                "stream_id": "Building_K_Cam1",
                "start_time": "2025-08-25T03:05:55.752Z",
                "end_time": "2025-08-25T03:06:15.752Z"
            },
            {
                "stream_id": "Building_K_Cam2",
                "start_time": "2025-08-25T03:10:00.000Z",
                "end_time": "2025-08-25T03:10:30.000Z"
            }
        ],
        "expiry_minutes": "1440",
        "container": "mp4"
    }
    ```

    Returns a list of video URLs that can be used to access the video files.
    """
    # Get the video storage URL tool
    get_video_storage_url_tool = await builder.get_tool(
        config.get_video_storage_url_tool, wrapper_type=LLMFrameworkEnum.LANGCHAIN
    )

    async def _vst_batch_video_storage(input_data: VSTBatchVideoStorageInput) -> VSTBatchVideoStorageOutput:
        """Process multiple stream/time ranges and return list of video URLs."""
        video_urls = []
        errors = []
        processed_count = 0

        # Determine defaults to use
        expiry_minutes = input_data.expiry_minutes or config.default_expiry_minutes
        container = input_data.container or config.default_container

        # Process each stream/time range
        for idx, time_range in enumerate(input_data.stream_time_ranges):
            try:
                logger.info(
                    f"Processing range {idx + 1}/{len(input_data.stream_time_ranges)}: "
                    f"stream_id={time_range.stream_id}, start_time={time_range.start_time}, "
                    f"end_time={time_range.end_time}"
                )

                # Prepare the input for vst_get_video_storage_url
                video_input = {
                    "stream_id": time_range.stream_id,
                    "start_time": time_range.start_time,
                    "end_time": time_range.end_time,
                    "expiry_minutes": expiry_minutes,
                    "container": container,
                }

                # Add configuration if specified
                if input_data.configuration:
                    video_input["configuration"] = input_data.configuration

                # Call the get_video_storage_url tool
                result_str = await get_video_storage_url_tool.ainvoke(input=video_input)

                # Parse and validate response
                try:
                    result = json.loads(result_str)
                except json.JSONDecodeError as e:
                    raise ValueError(f"Invalid JSON response: {e}") from e

                # Extract the video URL
                if not isinstance(result, dict):
                    raise ValueError(f"Expected dict response, got {type(result).__name__}")

                video_url = result.get("videoUrl")
                if not video_url:
                    raise ValueError("Missing 'videoUrl' in response")

                video_urls.append(video_url)
                processed_count += 1
                logger.info(f"Successfully retrieved URL: {video_url}")

            except Exception as e:
                error_msg = f"Error processing stream {time_range.stream_id} from {time_range.start_time} to {time_range.end_time}: {e!s}"
                logger.error(error_msg)
                errors.append(
                    {
                        "stream_id": time_range.stream_id,
                        "start_time": time_range.start_time,
                        "end_time": time_range.end_time,
                        "error": str(e),
                    }
                )

        # Log final results
        logger.info(
            f"Batch processing complete. Successfully processed {processed_count}/{len(input_data.stream_time_ranges)} ranges"
        )
        if errors:
            logger.warning(f"Encountered {len(errors)} errors during processing")

        return VSTBatchVideoStorageOutput(video_urls=video_urls, processed_count=processed_count, errors=errors)

    yield FunctionInfo.create(
        single_fn=_vst_batch_video_storage,
        description=_vst_batch_video_storage.__doc__,
        input_schema=VSTBatchVideoStorageInput,
        single_output_schema=VSTBatchVideoStorageOutput,
    )
